mapper.insert:
insert into payment_notify_log (
    id, order_id, notify_id, trade_no, trade_status, request_body_hash, processed, payload_json, created_at
) values (
    #{id}, #{orderId}, #{notifyId}, #{tradeNo}, #{tradeStatus}, #{requestBodyHash}, #{processed}, #{payloadJson}, now()
)
on conflict do nothing

mapper.sql:
where app_id = #{appId}

  and status = #{status}


  and (
    lower(user_email) like concat('%', lower(#{keyword}), '%')
    or lower(id) like concat('%', lower(#{keyword}), '%')
    or lower(coalesce(trade_no, '')) like concat('%', lower(#{keyword}), '%')
    or lower(plan_id) like concat('%', lower(#{keyword}), '%')
  )
